(function(){const previous=render;render=function(){previous();if(selected||page!=='项目台账')return;const filters=document.querySelector('.filters');if(!filters)return;const active=data.projects.filter(p=>!p.archived),star=active.filter(p=>p.starred).length,stale=active.filter(p=>(new Date(today()+'T12:00:00')-new Date((latest(p)?.date||created(p))+'T12:00:00'))/86400000>=14).length;const bar=document.createElement('div');bar.className='project-focus';bar.setAttribute('aria-label','项目快捷筛选');bar.innerHTML=[['all','全部项目',null],['starred','已关注',star],...(stale>0||projectFocus==='stale'?[['stale','长期未跟进',stale]]:[])].map(([k,n,c])=>`<button data-focus-project="${k}" aria-pressed="${projectFocus===k}" class="${projectFocus===k?'active':''}">${n}${c===null?'':'<small>'+c+'</small>'}</button>`).join('')+(projectFocus==='stale'?'<span class="focus-note">距最近跟进已满14天；无进展按登记日期计算</span>':'');filters.before(bar);bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{projectFocus=b.dataset.focusProject;render()})};})();
